{
  "status": "SUPPORTED",
  "task_summary": "Fasten component at marked location on workbench using tool found in storage, then leave tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where fastening occurs",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["desk", "table", "bench"],
        "required_properties": ["flat surface"]
      },
      {
        "id": "component",
        "entity_kind": "OBJECT",
        "function": "Object to be fastened",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["part", "piece", "object"],
        "required_properties": ["compatible with fastening"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "Device used to fasten",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "hammer", "wrench", "glue"],
        "required_properties": ["capable of fastening"]
      },
      {
        "id": "marked_location",
        "entity_kind": "FIXED_TARGET",
        "function": "Target spot on workbench",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["spot", "position", "area"],
        "required_properties": ["on workbench"]
      },
      {
        "id": "storage_container",
        "entity_kind": "OBJECT",
        "function": "Enclosed space to search",
        "required_count": 3,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "drawer", "box"],
        "required_properties": ["enclosed", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "component must be placed at marked_location",
        "participant_roles": ["component", "marked_location"]
      ,
      "required": true
      },
      {
        "id": "relation_2",
        "relation": "tool must be used on component",
        "participant_roles": ["tool", "component"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "search",
        "participant_roles": ["storage_container", "component", "tool"],
        "operation_count": 1
      },
      {
        "id": "operation_2",
        "operation": "fasten",
        "participant_roles": ["tool", "component", "marked_location"],
        "operation_count": 1
      },
      {
        "id": "operation_3",
        "operation": "place",
        "participant_roles": ["tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        {
          "label": "wooden desk",
          "visual_description": "Wooden surface with drawers underneath"
        }
      ],
      "component": [
        {
          "label": "yellow and black object on desk",
          "visual_description": "Rectangular object on a black tray on the desk"
        },
        {
          "label": "yellow block held by robot",
          "visual_description": "Yellow block held by the robotic arm in the third image"
        }
      ],
      "storage_container": [
        {
          "label": "blue cabinet",
          "visual_description": "Tall blue cabinet with a door behind the desk"
        },
        {
          "label": "left drawer",
          "visual_description": "Left drawer under the desk"
        },
        {
          "label": "right drawer",
          "visual_description": "Right drawer under the desk"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue cabinet",
        "visual_description": "Closed blue cabinet door",
        "reason": "Closed door, likely contains tools or spare parts"
      },
      {
        "id": "left_drawer",
        "label": "left drawer",
        "visual_description": "Closed drawer handle",
        "reason": "Closed handle, likely contains small tools"
      },
      {
        "id": "right_drawer",
        "label": "right drawer",
        "visual_description": "Closed drawer handle",
        "reason": "Closed handle, likely contains small tools"
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
